//! PR 6: deterministic CPU reference frame for the golden-frame test.
//!
//! This is **not** the GL2 GPU path: it rasterizes the same `FramePlan` on the
//! CPU with integer colour math, so the Python tool can reproduce the expected
//! RGBA8 bytes independently. It gives PR 6 a stable frame and draw-budget
//! check without needing wgpu parity or real X1650 hardware yet.

use super::passes::FramePlan;
use super::sections::{Blend, OverlayRect, Scene};

pub const GOLDEN_WIDTH: u32 = 80;
pub const GOLDEN_HEIGHT: u32 = 60;
/// Generated by `tools/legacy_gl_golden.py --generate`; treated as an
/// independent expected value, never rewritten by the Rust rasterizer.
#[cfg(test)]
const GOLDEN_RGBA: &[u8] = include_bytes!("../../../../benchmarks/graphics/legacy-gl-scene.rgba");

pub fn reference_frame() -> FramePlan {
    FramePlan::build(&Scene::reference()).expect("reference scene must build")
}

fn sky_pixel(y: u32, height: u32, top: [u8; 3], bottom: [u8; 3]) -> [u8; 3] {
    let t = y * 255 / height.saturating_sub(1).max(1);
    let channel = |a: u8, b: u8| {
        let diff = i32::from(b) - i32::from(a);
        (i32::from(a) + diff * (t as i32) / 255).clamp(0, 255) as u8
    };
    [
        channel(top[0], bottom[0]),
        channel(top[1], bottom[1]),
        channel(top[2], bottom[2]),
    ]
}

fn apply_fog(color: [u8; 4], fog: u8, fog_color: [u8; 3]) -> [u8; 4] {
    let f = u32::from(fog);
    let inv = 255 - f;
    let mix = |c: u8, fog_c: u8| ((u32::from(c) * inv + u32::from(fog_c) * f) / 255) as u8;
    [
        mix(color[0], fog_color[0]),
        mix(color[1], fog_color[1]),
        mix(color[2], fog_color[2]),
        color[3],
    ]
}

fn blend_channel(dst: u8, src: u8, alpha: u8) -> u8 {
    let a = u32::from(alpha);
    ((u32::from(src) * a + u32::from(dst) * (255 - a)) / 255) as u8
}

fn fill_opaque(out: &mut [u8], width: u32, height: u32, rect: &OverlayRect) {
    let x0 = (rect.x0.max(0) as u32).min(width);
    let y0 = (rect.y0.max(0) as u32).min(height);
    let x1 = (rect.x1.max(0) as u32).min(width);
    let y1 = (rect.y1.max(0) as u32).min(height);
    if x0 >= x1 || y0 >= y1 {
        return;
    }
    for y in y0..y1 {
        for x in x0..x1 {
            let at = ((y * width + x) * 4) as usize;
            out[at..at + 4].copy_from_slice(&rect.color);
        }
    }
}

impl FramePlan {
    /// RGBA8, top-down rows, deterministic integer arithmetic only.
    pub fn rasterize(&self, width: u32, height: u32) -> Vec<u8> {
        let mut out = vec![0_u8; (width * height * 4) as usize];
        for y in 0..height {
            let sky = sky_pixel(y, height, self.sky_top, self.sky_bottom);
            for x in 0..width {
                let at = ((y * width + x) * 4) as usize;
                out[at..at + 4].copy_from_slice(&[sky[0], sky[1], sky[2], 255]);
            }
        }

        for quad in &self.raster_quads {
            let color = apply_fog(quad.color, quad.fog, self.fog_color);
            let x0 = (quad.x0.max(0) as u32).min(width);
            let y0 = (quad.y0.max(0) as u32).min(height);
            let x1 = (quad.x1.max(0) as u32).min(width);
            let y1 = (quad.y1.max(0) as u32).min(height);
            if x0 >= x1 || y0 >= y1 {
                continue;
            }
            for y in y0..y1 {
                for x in x0..x1 {
                    if quad.checker && (x + y) & 1 == 0 {
                        continue;
                    }
                    let at = ((y * width + x) * 4) as usize;
                    match quad.blend {
                        Blend::Opaque | Blend::Cutout => {
                            out[at..at + 4].copy_from_slice(&color);
                        }
                        Blend::Alpha => {
                            out[at] = blend_channel(out[at], color[0], color[3]);
                            out[at + 1] = blend_channel(out[at + 1], color[1], color[3]);
                            out[at + 2] = blend_channel(out[at + 2], color[2], color[3]);
                        }
                    }
                }
            }
        }

        for rect in &self.hud {
            fill_opaque(&mut out, width, height, rect);
        }
        for rect in &self.lines {
            fill_opaque(&mut out, width, height, rect);
        }
        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::gfx21::passes::MAX_DRAWS;

    #[test]
    fn golden_frame_matches_the_independent_fixture() {
        let bytes = reference_frame().rasterize(GOLDEN_WIDTH, GOLDEN_HEIGHT);
        assert_eq!(bytes.len(), GOLDEN_RGBA.len());
        assert_eq!(bytes.len(), (GOLDEN_WIDTH * GOLDEN_HEIGHT * 4) as usize);
        assert_eq!(bytes.as_slice(), GOLDEN_RGBA);
    }

    #[test]
    fn golden_frame_is_written_for_ci() {
        let bytes = reference_frame().rasterize(GOLDEN_WIDTH, GOLDEN_HEIGHT);
        assert_eq!(bytes.as_slice(), GOLDEN_RGBA);
        if let Ok(path) = std::env::var("GFX21_GOLDEN_OUT") {
            std::fs::write(path, &bytes).expect("write golden RGBA output");
        }
    }

    #[test]
    fn golden_frame_is_deterministic() {
        let first = reference_frame().rasterize(GOLDEN_WIDTH, GOLDEN_HEIGHT);
        let second = reference_frame().rasterize(GOLDEN_WIDTH, GOLDEN_HEIGHT);
        assert_eq!(first, second);
    }

    #[test]
    fn fog_blend_and_sky_use_integer_exact_values() {
        assert_eq!(
            apply_fog([120, 90, 60, 255], 51, [90, 110, 130]),
            [114, 94, 74, 255]
        );
        assert_eq!(blend_channel(255, 0, 128), 127);
        assert_eq!(
            sky_pixel(0, GOLDEN_HEIGHT, [24, 36, 56], [72, 96, 120]),
            [24, 36, 56]
        );
        assert_eq!(
            sky_pixel(59, GOLDEN_HEIGHT, [24, 36, 56], [72, 96, 120]),
            [72, 96, 120]
        );
    }

    #[test]
    fn reference_frame_stays_inside_the_draw_budget() {
        assert!(reference_frame().draw_call_count() <= MAX_DRAWS);
    }
}
